class MockStorage {
  constructor() { this._dane = {}; }
  setItem(k, v) { this._dane[k] = String(v); }
  getItem(k) { return Object.prototype.hasOwnProperty.call(this._dane, k) ? this._dane[k] : null; }
  removeItem(k) { delete this._dane[k]; }
  clear() { this._dane = {}; }
}
