class MiniEventTarget {
  constructor() { this._h = {}; }
  addEventListener(typ, fn) { (this._h[typ] = this._h[typ] || []).push(fn); }
  dispatch(typ, e) { (this._h[typ] || []).forEach((fn) => fn(e)); }
}
const window = new MiniEventTarget();
