function migrujDoLocalStorage(sessionStorage, localStorage, klucz) {
  const wartosc = sessionStorage.getItem(klucz);
  if (wartosc !== null) {
    localStorage.setItem(klucz, wartosc);
    sessionStorage.removeItem(klucz);
  }
}
